'use strict';
const D = window.COURSE_DATA;
const $ = s => document.querySelector(s);
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const storageKey = 'database-study:v1';
function cleanState(s) {
  if (!s || typeof s !== 'object' || Array.isArray(s)) throw Error('备份格式不正确');
  const map = (name, fn) => Object.fromEntries(Object.entries(s[name] || {}).filter(([k,v]) => k.length < 200 && fn(v)).slice(0, 3000));
  return {done:map('done',v=>v===true), notes:map('notes',v=>typeof v==='string'&&v.length<=100000), wrong:map('wrong',v=>v===true), answers:map('answers',v=>Number.isInteger(v)&&v>=0&&v<4), drafts:map('drafts',v=>typeof v==='string'&&v.length<=100000), checks:map('checks',v=>v===true), labDone:map('labDone',v=>v===true), last:typeof s.last==='string'&&D.lessons.some(l=>l.id===s.last)?s.last:''};
}
let state;
try {state = cleanState(JSON.parse(localStorage.getItem(storageKey)) || {});} catch {state=cleanState({});}
function save(){try{localStorage.setItem(storageKey,JSON.stringify(state));}catch{toast('浏览器未能保存数据，可在复习页导出备份。');}}
let toastTimer;
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),2500);}
const icons = {home:'▦',courses:'▤',lab:'⌘',cases:'◇',review:'◷',homework:'✎'};
const moduleIcons={m1:'▤',m2:'⋈',m4:'⌘',m5:'⤢',m6:'{ }',m7:'◇'};
const moduleById=id=>D.modules.find(m=>m.id===id);
const lessonById=id=>D.lessons.find(l=>l.id===id);
const mLessons=id=>D.lessons.filter(l=>l.module===id);
function codebox(c,title='',dialect='Oracle'){
 const highlighted=esc(c).replace(/(--[^\n]*|&#39;[^\n]*?&#39;|\b(?:SELECT|FROM|WHERE|JOIN|LEFT|RIGHT|INNER|ON|AS|AND|OR|NOT|NULL|IS|IN|EXISTS|GROUP|BY|HAVING|ORDER|ASC|DESC|CREATE|OR|REPLACE|TABLE|VIEW|PROCEDURE|FUNCTION|TRIGGER|BEGIN|END|DECLARE|RETURN|IF|THEN|ELSE|ELSIF|LOOP|FOR|FETCH|OPEN|CLOSE|INTO|VALUES|UPDATE|SET|INSERT|DELETE|PRIMARY|KEY|FOREIGN|REFERENCES|CHECK|CONSTRAINT|EXCEPTION|WHEN)\b)/gi,m=>`<span class="${m.startsWith('--')?'comment':m.startsWith('&#39;')?'str':'kw'}">${m}</span>`);
 return `<div class="codebox"><div class="codebar"><b>${esc(title||'代码示例')}</b><span>${esc(dialect)}</span><button data-action="copy" aria-label="复制${esc(title||'代码')}">复制代码</button></div><pre><code>${highlighted}</code></pre></div>`;
}
function renderBlock(b,i){if(b.type==='text')return `<section class="article-block" id="b${i}"><h2>${esc(b.title)}</h2><p>${esc(b.text)}</p></section>`;if(b.type==='code')return `<section class="article-block" id="b${i}"><h2>${esc(b.title)}</h2>${codebox(b.code,'',b.dialect)}</section>`;if(b.type==='table')return `<section class="article-block" id="b${i}"><h2>${esc(b.title)}</h2>${renderTable(b.heads,b.rows)}</section>`;if(b.type==='steps')return `<section class="article-block" id="b${i}"><h2>${esc(b.title)}</h2><ol class="steps">${b.items.map(t=>`<li>${esc(t)}</li>`).join('')}</ol></section>`;return `<aside class="tip">${esc(b.text)}</aside>`;}
function renderTable(cols,rows){return `<div class="table-wrap"><table class="data-table"><thead><tr>${cols.map(c=>`<th scope="col">${esc(c)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c===null?'<span class="muted">NULL</span>':esc(c)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function navigation(section,module){$('#main-nav').innerHTML=[['home','学习总览'],['courses','全部课程'],['lab','SQL 实验室'],['homework','上机练习'],['cases','综合训练'],['review','复习与自测']].map(([id,label])=>`<a class="nav-link ${section===id?'active':''}" href="#/${id}" ${section===id?'aria-current="page"':''}><span class="nav-icon" aria-hidden="true">${icons[id]}</span>${label}${id==='lab'?'<span class="count">10</span>':id==='homework'?'<span class="count">32</span>':''}</a>`).join('');$('#module-nav').innerHTML=D.modules.map(m=>`<a class="module-link ${module===m.id?'active':''}" href="#/module/${m.id}" ${module===m.id?'aria-current="page"':''}><span class="num">${m.number}</span>${esc(m.title.replace('数据库技术基础','数据库基础').replace('关系数据库的理论基础','关系模型与关系代数').replace('关系数据库规范化','关系规范化').replace('数据库设计与综合应用','数据库设计'))}</a>`).join('');}
function moduleCard(m){const ls=mLessons(m.id),n=ls.filter(l=>state.done[l.id]).length;return `<a class="course-card" href="#/module/${m.id}"><div class="course-card-top"><span class="module-icon ${m.color}" aria-hidden="true">${moduleIcons[m.id]}</span><span class="chapter-num">CHAPTER ${m.number}</span></div><h3>${esc(m.title)}</h3><p>${esc(m.subtitle)}</p><div class="card-meta"><span>${ls.length} 节课程</span><span>·</span><span>${ls.reduce((n,l)=>n+l.minutes,0)} 分钟建议学习</span></div><div class="mini-progress"><span style="width:${n/ls.length*100}%"></span></div><div class="card-bottom"><span>${n?`已完成 ${n} / ${ls.length} 节`:'从这里开始'}</span><span class="card-arrow" aria-hidden="true">↗</span></div></a>`;}
function home(){const done=D.lessons.filter(l=>state.done[l.id]).length;const next=lessonById(state.last)||D.lessons.find(l=>!state.done[l.id])||D.lessons[0];const pct=Math.round(done/D.lessons.length*100);return `<section class="hero"><div><div class="eyebrow">A STRUCTURED WAY TO LEARN</div><h1>把数据库，<br>学成一套<em>思路。</em></h1><p>从关系模型到 SQL，从规范化到 PL/SQL。<br>沿着清晰的路径，把每个知识点连成解决问题的能力。</p><div class="hero-actions"><a class="btn" href="#/lesson/${next.id}">${done?'继续学习':'开始第一课'} <span>→</span></a><a class="text-link" href="#/homework">进入上机练习 ↗</a></div></div><div class="hero-diagram" role="img" aria-label="Student 和 Course 通过选课表 SC 建立多对多联系"><svg class="diagram-connector" viewBox="0 0 300 220" preserveAspectRatio="none"><path d="M30 45H100V95H150M260 65H220V95H150M245 180H200V130H150" fill="none" stroke="#adc294" stroke-dasharray="4 4"/></svg><div class="entity s">Student <small>PK sno</small></div><div class="db-stack"><svg viewBox="0 0 50 50" fill="none" stroke="#789664" stroke-width="1.4"><ellipse cx="25" cy="12" rx="17" ry="7"/><path d="M8 12v26c0 10 34 10 34 0V12M8 25c0 10 34 10 34 0"/></svg><b>让知识产生联系</b></div><div class="entity c">Course <small>PK cno</small></div><div class="entity sc">SC <small>sno + cno</small></div><span class="diagram-caption">RELATIONSHIPS MAKE SENSE.</span></div></section>
<div class="stats-row"><div class="stat"><span class="stat-icon">▤</span><div><strong>06</strong><span>知识模块</span></div></div><div class="stat"><span class="stat-icon">⌑</span><div><strong>31</strong><span>系统课程</span></div></div><div class="stat"><span class="stat-icon">⌘</span><div><strong>10</strong><span>SQL 交互实验</span></div></div><div class="stat"><span class="stat-icon">◇</span><div><strong>32</strong><span>上机练习任务</span></div></div></div>
<div class="overview-grid"><section><div class="section-heading"><h2>沿着知识地图前进 <small>YOUR LEARNING PATH</small></h2><a class="text-link" href="#/courses">查看全部 →</a></div><div class="course-grid">${D.modules.map(moduleCard).join('')}</div></section><aside class="dashboard-aside"><div class="aside-card"><span class="exam-badge">闭卷 · 综合应用</span><h3>从理解，到独立作答</h3><p>以 SQL 与 PL/SQL 编程为主线，<br>把设计题和编程题连起来。</p><ol class="path-list"><li><b>理清概念与关系</b><span>基础 / 关系代数</span></li><li><b>写对每一条查询</b><span>SQL / 在线实验</span></li><li><b>设计合理的数据结构</b><span>函数依赖 / 规范化</span></li><li><b>完成一个管理系统</b><span>PL/SQL / 综合训练</span></li></ol><a class="text-link" href="#/homework">练习上机 4–8 的题目 →</a></div><div class="aside-card tint"><h3>你的学习足迹</h3><div class="ring-row"><div class="progress-ring" style="--p:${pct}" data-label="${pct}%"></div><p>已掌握的每一节，<br>都是下一步的基础。<br><strong>${done} / 31 节已完成</strong></p></div><a class="text-link" href="#/review">复习薄弱知识点 →</a></div><div class="quote-note">“先理解数据之间的联系，<br>再写下连接它们的语句。”</div></aside></div>`;}
function heading(eye,title,sub){return `<div class="page-heading"><div class="eyebrow">${eye}</div><h1>${title}</h1><p>${sub}</p></div>`;}
function courses(){return heading('THE KNOWLEDGE MAP','全部课程','按课程章节系统学习，也可以直接进入你需要巩固的知识点。')+`<div class="course-grid">${D.modules.map(moduleCard).join('')}</div>`;}
function modulePage(id){const m=moduleById(id);if(!m)return notFound();const ls=mLessons(id);return `<div class="module-header"><span class="module-icon ${m.color}">${moduleIcons[id]}</span><div><div class="eyebrow">CHAPTER ${m.number}</div><h1 style="font-size:27px;margin:0 0 5px">${esc(m.title)}</h1><span class="muted" style="font-size:12px">${esc(m.subtitle)} · ${ls.length} 节课程</span></div></div><div class="lesson-list">${ls.map((l,i)=>`<a class="lesson-row" href="#/lesson/${l.id}"><span class="lesson-num">${String(i+1).padStart(2,'0')}</span><div><h3>${esc(l.title)}</h3><p>${esc(l.summary)}</p></div><div class="row-tail">${state.done[l.id]?'✓ 已完成':`${l.minutes} 分钟`}<span>↗</span></div></a>`).join('')}</div>`;}
function lessonPage(id){const l=lessonById(id);if(!l)return notFound();state.last=id;save();const index=D.lessons.indexOf(l);return `<a class="back-link" href="#/module/${l.module}">← ${esc(moduleById(l.module).title)}</a><div class="article-layout"><article class="article"><div class="eyebrow">CHAPTER ${moduleById(l.module).number} · ${l.minutes} MIN READ</div><h1>${esc(l.title)}</h1><div>${l.tags.map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div><p class="lead">${esc(l.summary)}</p>${l.blocks.map(renderBlock).join('')}<div class="article-nav">${index>0?`<a href="#/lesson/${D.lessons[index-1].id}">← 上一节</a>`:'<span></span>'}${index<D.lessons.length-1?`<a href="#/lesson/${D.lessons[index+1].id}">下一节：${esc(D.lessons[index+1].title)} →</a>`:'<a href="#/cases">开始综合训练 →</a>'}</div><label class="notes-label" for="lesson-notes">我的理解与疑问 · 自动保存</label><textarea id="lesson-notes" class="notes" data-note="${id}" placeholder="用自己的话解释一下，或记下想再练习的问题…">${esc(state.notes[id]||'')}</textarea></article><aside class="toc"><h3>本节内容</h3>${l.blocks.map((b,i)=>b.title?`<a href="#b${i}" data-scroll="b${i}">${esc(b.title)}</a>`:'').join('')}<button class="btn ${state.done[id]?'done':''}" data-action="complete" data-id="${id}">${state.done[id]?'✓ 已完成本节':'标记本节已完成'}</button><a class="text-link" href="#/quiz/${l.module}">练习本章概念 →</a><a class="text-link" href="#/lab">打开 SQL 实验室 →</a></aside></div>`;}
let activeLab='lab1', worker,requestCounter=0,pending=new Map(),workerReady=false;
function resetWorker(){if(worker)worker.terminate();for(const p of pending.values()){clearTimeout(p.timer);p.reject(Error('样例数据库已重置'));}pending.clear();workerReady=false;worker=new Worker('./sql-worker.js');worker.onmessage=e=>{const m=e.data;if(m.ready){workerReady=true;return;}const p=pending.get(m.id);if(p){clearTimeout(p.timer);pending.delete(m.id);m.error?p.reject(Error(m.error)):p.resolve(m);}};worker.onerror=()=>{for(const p of pending.values()){clearTimeout(p.timer);p.reject(Error('SQL 引擎加载失败，请刷新后重试。'));}pending.clear();};}
function sqlRequest(sql,grade){if(!worker)resetWorker();return new Promise((resolve,reject)=>{const id=++requestCounter;const timer=setTimeout(()=>{pending.delete(id);reject(Error('运行超过 5 秒，已重置数据库。请简化查询。'));resetWorker();},5000);pending.set(id,{resolve,reject,timer});worker.postMessage({id,sql,grade});});}
function labPage(id){if(id&&D.labs.some(l=>l.id===id))activeLab=id;const l=D.labs.find(l=>l.id===activeLab);return heading('SQL PLAYGROUND','SQL 实验室','在真实的样例数据上写查询，让每一条语句都有可以验证的结果。')+`<div class="lab-note"><strong>SQLite · 浏览器内运行</strong>　支持查询、建表与数据修改，数据在离开或重置后恢复。Oracle 的 PL/SQL、VARCHAR2、NVL、MINUS 等写法请按课程标签在 Oracle 环境使用。每道实验在独立的初始数据上检验结果。</div><div class="lab-layout"><aside class="lab-menu"><h3>查询挑战</h3>${D.labs.map(t=>`<button data-action="lab-select" data-id="${t.id}" class="${t.id===activeLab?'active':''}">${state.labDone[t.id]?'✓ ':''}${esc(t.title)}</button>`).join('')}<button data-action="lab-free" class="free-query">自由查询 ↗</button></aside><section class="panel"><span class="tag">${l.id==='lab10'?'包含排序校验':'按结果检验'}</span><h2 style="margin:14px 0 10px">${esc(l.title)}</h2><p>${esc(l.goal)}</p><div class="schema-tabs" aria-label="查看样例表"><button data-action="schema" data-id="Student">Student · 6 行</button><button data-action="schema" data-id="Course">Course · 4 行</button><button data-action="schema" data-id="SC">SC · 11 行</button></div><details style="margin:10px 0 18px"><summary>查看字段与联系</summary>${renderTable(['表','字段','联系'],[['Student','sno, sname, dept, age','PK: sno'],['Course','cno, cname, credit, pcno','PK: cno；pcno 引用 Course'],['SC','sno, cno, grade','PK: (sno,cno)；两个外键']])}</details><label for="sql-editor" class="sr-only">SQL 编辑器</label><textarea id="sql-editor" class="sql-editor" spellcheck="false">${esc(state.drafts[l.id]||l.starter)}</textarea><div class="editor-actions"><button class="btn" data-action="sql-run">▶ 运行查询</button><button class="btn secondary" data-action="sql-grade">检验答案</button><button class="text-link" data-action="sql-reset">重置样例库</button><span class="key-hint">⌘ / Ctrl + Enter 运行</span></div><details><summary>思路提示</summary><p>${esc(l.hint)}</p></details><details><summary>参考写法</summary>${codebox(l.answer,'参考答案','SQLite')}</details><div id="sql-output" aria-live="polite"><div class="feedback">写下你的 SQL，然后运行查看结果。点击表名可预览数据。</div></div></section></div>`;}
function caseList(){return heading('THINK IN SYSTEMS','综合训练','按闭卷综合题的方式练习：先独立作答，再核对参考与评分要点。')+`<div class="case-grid">${D.cases.map((c,i)=>`<article class="case-card"><span class="tag">${esc(c.label)}</span><div class="eyebrow" style="margin:15px 0 0">CASE 0${i+1}</div><h2>${esc(c.title)}</h2><p>${esc(c.summary)}</p><div class="case-meta">${c.tasks.length} 个分步任务 · 建议 ${c.minutes} 分钟</div><a class="btn secondary" href="#/case/${c.id}">开始作答 →</a></article>`).join('')}</div><div class="feedback" style="margin-top:25px">综合题草稿自动保存在本机。评分要点用于自我核对；SQL 实验室中的查询挑战可自动比较结果。</div>`;}
function casePage(id){const c=D.cases.find(c=>c.id===id);if(!c)return notFound();return `<a class="back-link" href="#/cases">← 全部综合训练</a>${heading('CASE STUDY',esc(c.title),esc(c.summary))}<div class="requirements"><h2>业务需求</h2>${esc(c.requirement)}</div><details><summary>展开关系结构示意 · 建议先独立设计</summary><div class="er-diagram">${c.entities.map(en=>`<div class="er-node"><b>${esc(en[0])}</b>${en.slice(1).map(s=>`<span>${esc(s)}</span>`).join('')}</div>`).join('')}</div><p class="er-caption">${esc(c.relations)}</p></details>${c.tasks.map((t,i)=>`<section class="case-task"><h2>${esc(t.title)}</h2><p>${esc(t.prompt)}</p><label class="sr-only" for="draft-${i}">第 ${i+1} 题作答</label><textarea id="draft-${i}" class="answer-area" data-draft="${id}:${i}" spellcheck="false" placeholder="在这里写下你的分析、关系模式或代码…">${esc(state.drafts[id+':'+i]||'')}</textarea><span class="answer-save">草稿自动保存 · 请先独立思考</span><details><summary>展开参考答案与评分要点</summary><p class="reference-answer">${esc(t.answer)}</p>${t.code?codebox(t.code,'参考代码','Oracle'):''}<div class="rubric">${t.checks.map((check,j)=>`<label><input type="checkbox" data-check="${id}:${i}:${j}" ${state.checks[id+':'+i+':'+j]?'checked':''}>${esc(check)}</label>`).join('')}</div></details></section>`).join('')}`;}
let quiz={ids:[],index:0,selected:null,correct:0,module:'all',wrongOnly:false};
function quizStart(module='all',wrongOnly=false){quiz={ids:D.quiz.filter(q=>(module==='all'||q.module===module)&&(!wrongOnly||state.wrong[q.id])).map(q=>q.id),index:0,selected:null,correct:0,module,wrongOnly};}
function quizPage(module){if(module!==undefined)quizStart(module==='wrong'?'all':module,module==='wrong');const q=D.quiz.find(q=>q.id===quiz.ids[quiz.index]);return heading('CHECK YOUR UNDERSTANDING','概念自测','用短题检查概念与易错点，再把理解应用到综合任务。')+`<div class="quiz-controls"><label for="quiz-module">范围</label><select id="quiz-module"><option value="all">全部模块</option>${D.modules.map(m=>`<option value="${m.id}" ${quiz.module===m.id?'selected':''}>${esc(m.title)}</option>`).join('')}</select><label><input id="quiz-wrong" type="checkbox" ${quiz.wrongOnly?'checked':''}>只练错题</label><button class="btn secondary small" data-action="quiz-restart">重新开始</button><span class="quiz-status">共 ${quiz.ids.length} 题 · 错题 ${Object.keys(state.wrong).length} 道</span></div>${!q?`<div class="empty-state"><h2>${quiz.ids.length?'本轮自测已完成':'当前范围暂无题目'}</h2><p>${quiz.ids.length?`本轮答对 ${quiz.correct} / ${quiz.ids.length} 道。答错的题已加入错题记录。`:'可以切换模块或取消“只练错题”。'}</p><a class="btn secondary" href="#/review">返回复习中心</a></div>`:`<section class="quiz-card"><div class="question-meta"><span>${esc(moduleById(q.module).title)}</span><span>${String(quiz.index+1).padStart(2,'0')} / ${String(quiz.ids.length).padStart(2,'0')}</span></div><div class="mini-progress"><span style="width:${quiz.index/quiz.ids.length*100}%"></span></div><h2>${esc(q.question)}</h2>${q.options.map((o,i)=>`<button data-action="quiz-answer" data-id="${i}" class="quiz-option ${quiz.selected!==null?(i===q.answer?'correct':i===quiz.selected?'wrong':''):''}" ${quiz.selected!==null?'disabled':''}><b>${'ABCD'[i]}</b><span>${esc(o)}</span></button>`).join('')}${quiz.selected!==null?`<div class="feedback ${quiz.selected===q.answer?'':'error'}">${quiz.selected===q.answer?'✓ 回答正确。':'正确答案：'+ 'ABCD'[q.answer]+'。'} ${esc(q.explanation)}</div>`:''}<div class="quiz-bottom"><small>作答后查看解析 · 答对会移出错题记录</small>${quiz.selected!==null?`<button class="btn small" data-action="quiz-next">${quiz.index===quiz.ids.length-1?'查看本轮结果':'下一题'} →</button>`:''}</div></section>`}`;}
const checklist=[['设计与模型',['能识别实体、属性、联系基数','能把 m:n 联系转成独立关系','能标出所有主键、外键和引用目标']],['规范化',['能由业务规则写出函数依赖','能求闭包并找全候选码','能区分部分依赖与传递依赖','能给出 3NF 分解与理由']],['SQL 查询',['会连接、分组、HAVING 与聚合','会处理 NULL 与外连接','能查询并列最高、无记录与选齐全部','会创建表、约束、索引与视图']],['PL/SQL 编程',['会变量、SELECT INTO 与异常处理','能写出游标完整生命周期','会带 IN / OUT 的过程与 RETURN 函数','理解触发器 OLD / NEW 和变异表限制']]];
function review(){const done=D.lessons.filter(l=>state.done[l.id]).length;const attempted=Object.keys(state.answers).length;return heading('REVIEW & RECALL','复习与自测','从掌握清单中找到薄弱点，再用实验与综合题巩固。')+`<div class="stats-row"><div class="stat"><div><strong>${done}<small> / 31</small></strong><span>已完成课程</span></div></div><div class="stat"><div><strong>${Object.keys(state.labDone).length}<small> / 10</small></strong><span>已通过 SQL 实验</span></div></div><div class="stat"><div><strong>${attempted}<small> / 42</small></strong><span>已作答自测</span></div></div><div class="stat"><div><strong>${Object.keys(state.wrong).length}</strong><span>待巩固错题</span></div></div></div><div class="section-heading"><h2>考试掌握清单</h2><div style="display:flex;gap:10px"><a class="btn small secondary" href="#/quiz/wrong">复习错题</a><a class="btn small" href="#/quiz/all">开始概念自测 →</a></div></div><div class="review-grid">${checklist.map(([title,items],i)=>`<section class="review-card"><h3>${title}</h3><ul class="check-list">${items.map((s,j)=>`<li><input id="check-${i}-${j}" type="checkbox" data-check="exam:${i}:${j}" ${state.checks['exam:'+i+':'+j]?'checked':''}><label for="check-${i}-${j}">${s}</label></li>`).join('')}</ul></section>`).join('')}</div><div class="backup-actions"><button class="btn secondary small" data-action="export">导出学习备份</button><button class="btn secondary small" data-action="import">导入学习备份</button><a class="text-link" href="#/lesson/exam-method">查看综合题作答方法 →</a><input id="import-file" class="sr-only" type="file" accept="application/json,.json" aria-label="选择学习备份文件"></div><p class="muted" style="font-size:11px;margin-top:15px">进度、错题和草稿保存在当前设备的浏览器中。更换设备前，可导出 JSON 备份再导入。</p>`;}
function about(){return `<div class="about">${heading('ABOUT THIS CLASSROOM','学得清楚，用得起来。','这里是一套以数据库原理与应用为主线的学习与复习空间。')}<div class="panel"><h2>内容与学习路径</h2><p>课程根据提供的数据库课件与考试重点重新组织，保留第 1、2、4、5、6 章的课程脉络，并从考试重点补充第 7 章数据库设计。不补造缺失的第 3 章。</p><p>31 节课程讲解基础与例题，10 个 SQL 实验验证查询，3 个管理系统案例包含 14 个综合任务；另设上机 4、5、6、7–8 四组原题练习，共 32 个任务。42 道概念题帮助检查理解；综合训练对应闭卷综合题的作答方式。</p><h2>数据库方言</h2><p>课程中的 PL/SQL 与综合案例采用 Oracle 语法。上机 4–8 按提供的 MySQL 练习脚本整理，参考解法标注为 MySQL 8.0.16+。代码块会标明 Oracle、通用 SQL 或 SQLite。SQL 实验室采用本地打包的 sql.js / SQLite 引擎，真正执行输入的 SQL；它不执行 Oracle 的存储过程、函数或触发器语法。</p><p>MySQL 的 <code>AUTO_INCREMENT</code>、<code>ADD INDEX</code> 与 Oracle 的 <code>VARCHAR2</code>、<code>%TYPE</code> 属于各自方言，不能混写。查看 <a href="./reference/dialects.md">方言速查</a>。</p><h2>实验怎么判定</h2><p>“运行查询”在当前临时样例库执行；“检验答案”在全新的初始样例库执行查询，与参考结果比较。比较输出列顺序、值、行数和重复记录；第 10 题额外检查行顺序。相同样例结果不等于对所有数据都正确，请结合课程推理。一次执行超过 5 秒会重置引擎。</p><h2>学习数据与备份</h2><p>进度与草稿存储在浏览器 localStorage，无需注册。不同设备、浏览器和网站地址之间不会自动同步。可在“复习与自测”导出或导入备份。综合题评分清单由你自评，系统不自动给开放答案打分。</p><h2>继续编辑与部署</h2><p>这是可独立运行的静态网站，支持 GitHub Pages 的项目子路径。仓库中的 README 说明本地启动、内容维护和 GitHub Actions 部署方法。原始课件未打包进公开网站源码。</p><p><a href="./reference/coverage.md">查看课程覆盖说明</a> · <a href="./reference/oracle-course.sql" download>下载 Oracle 综合案例脚本</a></p><h2>技术参考</h2><p><a href="https://docs.oracle.com/en/database/oracle/oracle-database/19/lnpls/processing-query-result-sets.html" target="_blank" rel="noopener">Oracle PL/SQL 查询结果处理</a> · <a href="https://www.sqlite.org/lang_select.html" target="_blank" rel="noopener">SQLite SELECT</a> · <a href="https://sql.js.org/documentation/" target="_blank" rel="noopener">sql.js 文档</a></p></div></div>`;}

const datasetNames={construction:'基建供需',parcel:'快递管理',sales:'销售管理',library:'图书借阅',ecommerce:'电子商务'};
function homeworkList(){return heading('PRACTICE FROM CLASS','上机练习 4–8','按题组完成 32 个任务：先独立作答，再对照 MySQL 参考解法。')+`<div class="case-grid homework-grid">${D.homework.map((g,i)=>`<article class="case-card"><span class="tag">${esc(g.label)}</span><div class="eyebrow" style="margin:15px 0 0">PRACTICE 0${i+1}</div><h2>${esc(g.title)}</h2><p>${esc(g.summary)}</p><div class="case-meta">${g.tasks.length} 道任务 · 建议 ${g.minutes} 分钟 · MySQL</div><a class="btn secondary" href="#/homework/${g.id}">进入本组练习 →</a></article>`).join('')}</div><div class="feedback" style="margin-top:24px">本区按上机题要求组织。MySQL 存储过程使用 DELIMITER、DECLARE HANDLER 等语法；Oracle PL/SQL 请参照课程与综合训练。每题草稿自动保存。</div>`;}
function homeworkPage(id){const g=D.homework.find(g=>g.id===id);if(!g)return notFound();return `<a class="back-link" href="#/homework">← 全部上机练习</a>${heading('CLASS PRACTICE',esc(g.title),esc(g.summary))}<div class="requirements"><h2>业务规则与统计口径</h2>${esc(g.requirement)}<div class="backup-actions">${g.schemas.map(s=>`<a class="btn secondary small" href="./reference/sql/${s}.sql" download>下载${datasetNames[s]}建表与数据 ↓</a>`).join('')}</div><p style="font-size:11px;margin:14px 0 0">环境：${esc(g.dialect)}。不同数据集请使用各自独立的学习数据库；相同表名不代表同一业务。</p></div>${g.tasks.map((t,i)=>`<section class="case-task"><span class="tag">${datasetNames[t.dataset]} · ${g.dialect}</span><h2 style="margin-top:12px">${esc(t.title)}</h2><p>${esc(t.prompt)}</p><label class="sr-only" for="hw-draft-${i}">第 ${i+1} 题作答</label><textarea id="hw-draft-${i}" class="answer-area" data-draft="${id}:${i}" spellcheck="false" placeholder="先写自己的 SQL、分析或 E-R 设计…">${esc(state.drafts[id+':'+i]||'')}</textarea><span class="answer-save">草稿自动保存</span><details><summary>展开解题思路、参考代码与核对清单</summary><p class="reference-answer">${esc(t.answer)}</p>${t.code?codebox(t.code,'参考解法',g.dialect):''}<div class="rubric">${t.checks.map((c,j)=>`<label><input type="checkbox" data-check="${id}:${i}:${j}" ${state.checks[id+':'+i+':'+j]?'checked':''}>${esc(c)}</label>`).join('')}</div></details></section>`).join('')}`;}

function notFound(){return `<div class="empty-state"><h2>没有找到这个页面</h2><a class="btn" href="#/home">返回学习总览</a></div>`;}
let currentRoute='';
function route(){const hash=location.hash||'#/home';if(!hash.startsWith('#/'))return;if(worker && currentRoute.startsWith('#/lab') && !hash.startsWith('#/lab')){worker.terminate();worker=null;for(const p of pending.values()){clearTimeout(p.timer);p.reject(Error('已离开实验室'));}pending.clear();}currentRoute=hash;const [name,id]=hash.slice(2).split('/');let html='',section=name,module;const labels={home:'学习总览',courses:'全部课程',lab:'SQL 实验室',cases:'综合训练',review:'复习与自测',about:'课程说明',quiz:'概念自测',homework:'上机练习'};if(name==='home')html=home();else if(name==='courses')html=courses();else if(name==='module'){html=modulePage(id);section='courses';module=id;}else if(name==='lesson'){html=lessonPage(id);section='courses';module=lessonById(id)?.module;}else if(name==='lab')html=labPage(id);else if(name==='homework')html=id?homeworkPage(id):homeworkList();else if(name==='cases')html=caseList();else if(name==='case'){html=casePage(id);section='cases';}else if(name==='review')html=review();else if(name==='quiz'){html=quizPage(id||'all');section='review';}else if(name==='about')html=about();else html=notFound();$('#main').innerHTML=html;navigation(section,module);$('#breadcrumb').textContent=module?moduleById(module)?.title||'课程':labels[name]||(name==='case'?'综合训练':'学习空间');document.title=(name==='lesson'?lessonById(id)?.title:labels[name]||moduleById(module)?.title||'学习空间')+' · 数据库研习室';window.scrollTo(0,0);closeMenu();}
function refreshQuiz(){const y=window.scrollY;$('#main').innerHTML=quizPage();window.scrollTo(0,y);}
function closeMenu(){$('#sidebar').classList.remove('open');$('#menu-toggle').setAttribute('aria-expanded','false');}
async function runSQL(grade=false,sql){const editor=$('#sql-editor');if(!editor)return;const query=sql||editor.value;if(!query.trim()){toast('请先输入 SQL。');return;}if(/\b(?:DECLARE|DBMS_OUTPUT|VARCHAR2|PROCEDURE|%TYPE|%ROWTYPE)\b/i.test(query)){$('#sql-output').innerHTML='<div class="feedback error">这段代码包含 Oracle / PL/SQL 写法。实验区使用 SQLite，请使用课程标注的通用 SQL 查询。</div>';return;}const routeAtStart=currentRoute;const buttons=document.querySelectorAll('[data-action="sql-run"],[data-action="sql-grade"]');buttons.forEach(b=>b.disabled=true);const l=D.labs.find(l=>l.id===activeLab);$('#sql-output').innerHTML='<div class="loading">正在执行 SQL…</div>';try{const result=await sqlRequest(query,grade?{answer:l.answer,order:l.order}:undefined);if(routeAtStart!==currentRoute)return;let html='';if(grade){if(result.pass){state.labDone[l.id]=true;save();const item=document.querySelector('[data-action="lab-select"][data-id="'+l.id+'"]');if(item)item.textContent='✓ '+l.title;toast('本题检验通过');}html+=`<div class="feedback ${result.pass?'':'error'}">${result.pass?'✓ 查询结果与参考一致。':'结果与参考不一致，请检查输出列顺序、行数、重复行、NULL'+(l.order?'及排序':'')+'。'} 检验基于初始样例库。</div>`;}html+=(result.results.length?result.results.map((r,i)=>`<div class="result-head">结果 ${i+1}<small>${r.total} 行${r.total>300?'，显示前 300 行':''}</small></div>${renderTable(r.columns,r.values)}`).join(''):`<div class="feedback">执行完成。${result.changed} 行数据受影响；本次没有返回结果集。</div>`);$('#sql-output').innerHTML=html;}catch(e){if(routeAtStart===currentRoute)$('#sql-output').innerHTML=`<div class="feedback error">${esc(e.message)}</div>`;}finally{buttons.forEach(b=>b.disabled=false);}}
document.addEventListener('click',async e=>{const scroll=e.target.closest('[data-scroll]');if(scroll){e.preventDefault();document.getElementById(scroll.dataset.scroll)?.scrollIntoView({behavior:'smooth'});return;}const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,id=el.dataset.id;if(a==='complete'){state.done[id]?delete state.done[id]:state.done[id]=true;save();el.classList.toggle('done',!!state.done[id]);el.textContent=state.done[id]?'✓ 已完成本节':'标记本节已完成';toast(state.done[id]?'已记录本节学习进度':'已取消完成标记');}else if(a==='copy'){const s=el.closest('.codebox').querySelector('code').textContent;try{await navigator.clipboard.writeText(s);toast('代码已复制');}catch{toast('请选中代码手动复制');}}else if(a==='lab-select'){state.drafts[activeLab]=$('#sql-editor').value;save();activeLab=id;resetWorker();location.hash='#/lab/'+id;if(location.hash===currentRoute)route();}else if(a==='lab-free'){$('#sql-editor').value='-- 自由查询：可使用 SELECT、CREATE、INSERT、UPDATE、DELETE\nSELECT * FROM Student;';$('#sql-output').innerHTML='<div class="feedback">自由查询模式：运行语句探索样例数据。重置可恢复初始数据。</div>';}else if(a==='sql-run')await runSQL();else if(a==='sql-grade')await runSQL(true);else if(a==='schema')await runSQL(false,`SELECT * FROM ${id};`);else if(a==='sql-reset'){resetWorker();$('#sql-output').innerHTML='<div class="feedback">样例库已恢复初始数据。</div>';toast('已重置样例库');}else if(a==='quiz-answer'){if(quiz.selected!==null)return;const q=D.quiz.find(q=>q.id===quiz.ids[quiz.index]);quiz.selected=Number(id);state.answers[q.id]=Number(id);if(Number(id)===q.answer){quiz.correct++;delete state.wrong[q.id];}else state.wrong[q.id]=true;save();refreshQuiz();}else if(a==='quiz-next'){quiz.index++;quiz.selected=null;refreshQuiz();}else if(a==='quiz-restart'){quizStart($('#quiz-module').value,$('#quiz-wrong').checked);refreshQuiz();}else if(a==='export'){const blob=new Blob([JSON.stringify({version:1,exportedAt:new Date().toISOString(),...state},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='数据库学习备份-'+new Date().toISOString().slice(0,10)+'.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('学习备份已导出');}else if(a==='import')$('#import-file').click();});
document.addEventListener('input',e=>{const el=e.target;if(el.dataset.note){state.notes[el.dataset.note]=el.value;save();}else if(el.dataset.draft){state.drafts[el.dataset.draft]=el.value;save();}else if(el.id==='sql-editor'){state.drafts[activeLab]=el.value;save();}});
document.addEventListener('change',async e=>{const el=e.target;if(el.dataset.check){el.checked?state.checks[el.dataset.check]=true:delete state.checks[el.dataset.check];save();}else if(el.id==='quiz-module'||el.id==='quiz-wrong'){quizStart($('#quiz-module').value,$('#quiz-wrong').checked);refreshQuiz();}else if(el.id==='import-file'&&el.files[0]){try{if(el.files[0].size>5e6)throw Error('备份文件过大');const imported=JSON.parse(await el.files[0].text());if(imported.version!==1)throw Error('备份版本不支持');const cleaned=cleanState(imported);for(const key of ['done','notes','wrong','answers','drafts','checks','labDone'])state[key]={...state[key],...cleaned[key]};save();route();toast('已合并导入学习记录');}catch(err){toast('导入失败：'+err.message);}}});
$('#menu-toggle').addEventListener('click',()=>{const open=$('#sidebar').classList.toggle('open');$('#menu-toggle').setAttribute('aria-expanded',String(open));});$('#scrim').addEventListener('click',closeMenu);
function showSearch(){$('#search-dialog').showModal();$('#search-input').value='';search('');$('#search-input').focus();}
function search(q){q=q.trim().toLocaleLowerCase();const results=q?D.lessons.filter(l=>JSON.stringify(l).toLocaleLowerCase().includes(q)):D.lessons.filter(l=>['closure-keys','cursor','aggregate','er-conversion'].includes(l.id));$('#search-results').innerHTML=results.length?results.slice(0,20).map(l=>`<a class="search-result" href="#/lesson/${l.id}"><b>${esc(l.title)}</b><small>${esc(moduleById(l.module).title)} · ${esc(l.summary)}</small></a>`).join(''):`<div class="search-empty">没有找到“${esc(q)}”，试试更短的关键词。</div>`;}
$('#search-open').addEventListener('click',showSearch);$('#search-close').addEventListener('click',()=>$('#search-dialog').close());$('#search-input').addEventListener('input',e=>search(e.target.value));$('#search-results').addEventListener('click',e=>{if(e.target.closest('a'))$('#search-dialog').close();});$('#search-dialog').addEventListener('click',e=>{if(e.target===$('#search-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
document.addEventListener('keydown',e=>{const typing=['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName);if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if(!$('#search-dialog').open)showSearch();}else if(e.key==='/'&&!typing){e.preventDefault();showSearch();}else if(e.key==='Enter'&&(e.metaKey||e.ctrlKey)&&document.activeElement.id==='sql-editor'){e.preventDefault();runSQL();}else if(e.key==='Escape')closeMenu();});
window.addEventListener('hashchange',route);window.addEventListener('beforeunload',()=>worker?.terminate());route();
